def compile_regexp(session, source, listing=None):
    """
    Compile regexp value

    Compile regexp value and return either an unevaluated adaptive value or a
    string containing the compiler listing. The listing is a human-oriented
    dump (value tree interleaved with source, plus ---Symbols tables) for
    Fiddle and debugging — not pure JSON (use stringify) and not Adaptive
    compiled-form text (use decompile).

    Args:
        source (object): regexp string to compile
        listing (object): If specified, a human compiler listing is produced
            instead of an unevaluated compiled value (tree + ---Symbols; not
            recompilable). Use decompile() for Adaptive compiled-form text and
            stringify() for pure JSON of evaluated data. This parameter can be
            an integer between 0 and 10 or a string that is used for
            indentation. If 0 is specified, no whitespace is added to the
            resulting string. If 1 through 10 is specified, that number of
            spaces is used.

    Returns:
        object:
    """

    request = session.Request()

    action = {
        "function": "compile<regexp>",
        "source": source
    }

    if listing != None:
        action['listing'] = listing

    request.add_action(action)

    response = request.perform()
    if response.get('status') == 'error':
        raise Exception(response.get('error'))

    return response['actions'][0]['result']

